//import "mathjax/es5/tex-chtml.js"

// display the lif logo if passed
// choose content
const parameters = new URLSearchParams(document.location.search);
const branding = parameters.get("branding");
let startingContent = parameters.get("content");
if (branding === "lif") {
  document.getElementById("logo_lif").style.display = "inline";
  document.getElementById("logo_bridge").style.width = "50%";
  document.getElementById("brands").style.justifyContent = "space-between";
}

// create a random 6 digit ID
var sessionId = Math.floor(Math.random() * 90000 + 10000);
var requestId = 0; // used to be able to have multiple requests at the same time (frontend cancel)

// variables concerning the settings menu
var settingsOpen = false;
var currentMenu = "";
const defaultSettings = {
  avatar: "avatar_muhammad",
  language: "language_multilingual",
  "playback-speed": "playback-speed_1.00",
  autostop: "0.7 0.3 1",
  creativity: "creativity_medium",
  "gpt-model": "gpt-model_4o",
  prompt: "",
  content: "content_none",
  "show-start-menu": "show-start-menu_on",
  stt: "stt_api",
};
var selectedAvatar;
// the settings that can be selected and their possible values, free choice fields (e.g. autostop, prompt) excluded
// needed to keep localstorage entrys up to date for all users in case of changes
const allowedSettings = {
  avatar: [
    "zara",
    "muhammad",
    "anna",
    "leo",
    "zola",
    "amari",
    "aki",
    "wei",
    "rose",
    "tom",
    "maya",
    "shonith",
  ],
  language: [
    "multilingual",
    "en",
    "ar",
    "hi",
    "de",
    "es",
    "pt",
    "sv",
    "nl",
    "ru",
    "fr",
    "zh",
  ],
  "playback-speed": [
    "0.25",
    "0.50",
    "0.75",
    "1.00",
    "1.25",
    "1.50",
    "1.75",
    "2.00",
  ],
  creativity: ["low", "medium", "high"],
  "gpt-model": ["3.5", "4", "4o"],
  content: ["none", "mslf", "ss-doe", "ss-yellow"],
  "show-start-menu": ["on", "off"],
  stt: ["api", "tiny", "small", "base", "medium", "large"],
};
const autostopOptions = [
  "autostop_positive",
  "autostop_negative",
  "autostop_seconds",
];

// variables concerning the logic of the program
var isCancelled = false; // activates when pressing cancel button, stops audio playing
var previousQuestion = ""; // used to determine when the send button was clicked multiple times in a row
var firstSetup = true; // specific behaviour for lazy loading

// the audioelements are declared and initialized only later following the user input
var audioElement;
var pingSound;
var isMuted = false;

// queues for audio and blenddata
let audioQueue = [];
let blenddataQueue = [];

// the variables for wake word detection (wwd)
var porcupine;
var wakeWordActive = false; // option to disable wwd

